#!/bin/sh
# install-git-hooks.sh — installs the post-commit hook that keeps
# whoof-commit-log.xlsx in sync with the repo automatically.
#
# Git hooks live in .git/hooks/, which is NOT tracked by git, so this has to be run once
# per clone/machine. Safe to re-run — it just overwrites the hook file.

set -e
REPO_ROOT="$(git rev-parse --show-toplevel)"
HOOK="$REPO_ROOT/.git/hooks/post-commit"

cat > "$HOOK" <<'EOF'
#!/bin/sh
# Auto-generated by scripts/install-git-hooks.sh — regenerates whoof-commit-log.xlsx after
# every commit. Never blocks or fails the commit (errors are swallowed).
node "$(git rev-parse --show-toplevel)/scripts/generate-commit-log.js" >/dev/null 2>&1 || true
exit 0
EOF

chmod +x "$HOOK"
echo "Installed post-commit hook → $HOOK"
